song.stan

    data {
      int<lower=0> NOBS;
      real<lower=0> x[NOBS];
      int<lower=0> Y[NOBS];
      int iszero[NOBS];
    }
    parameters{
      real alpha1;
      real alpha2;
      real beta1;
      real<lower=0> beta2;
      real<lower=-1> beta3;
    }
    model{
      alpha1 ~ normal(0,100);
      alpha2 ~ normal(0,100); // drop const T[0,];

      beta1 ~ normal(0, 100);
      beta2 ~ normal(0, 100); // drop const T[0,];
      beta3 ~ normal(0, 100); // drop const T[-1,];

      for (i in 1:NOBS) {
        real lambda;
        real pi;
        pi <- inv_logit(alpha1 + alpha2 * x[i]);
        lambda <- exp(beta1 - beta2 * x[i] + beta3 * log(x[i]));
        lp__ <- lp__ + if_else(iszero[i],
                               log(pi + (1 - pi) * exp(-lambda)),
                               log1m(pi) + poisson_log(Y[i], lambda) );
      }
    }
